package com.github.tartaricacid.touhoulittlemaid.ai.agent.context.tools;

import com.github.tartaricacid.touhoulittlemaid.ai.agent.context.AbstractMaidContext;
import com.github.tartaricacid.touhoulittlemaid.ai.agent.context.GameContextRegister;
import com.github.tartaricacid.touhoulittlemaid.entity.passive.EntityMaid;
import com.google.common.collect.Lists;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.phys.AABB;
import net.minecraftforge.registries.ForgeRegistries;
import org.apache.commons.lang3.StringUtils;

public final class NearbyEntityMaidContexts {
    public static final String CATEGORY = "nearby_entities";
    private static final String SUMMARY = "Nearby living entities, including type, entity id, distance to self, and distance to user.";
    private static final int MAX_ENTITIES = 20;

    private NearbyEntityMaidContexts() {
    }

    public static void registerAll(GameContextRegister register) {
        register.registerCategory(CATEGORY, SUMMARY, false);
        register.registerContext(CATEGORY, new NearbyEntitiesContext());
    }

    private static final class NearbyEntitiesContext
    extends AbstractMaidContext {
        private NearbyEntitiesContext() {
            super(NearbyEntityMaidContexts.CATEGORY, "List of nearby living entities with id and distances");
        }

        @Override
        public String getValue(EntityMaid maid) {
            AABB scanBox = maid.getTask().searchDimension(maid);
            List entities = maid.f_19853_.m_6443_(LivingEntity.class, scanBox, e -> e != maid && e.m_6084_());
            if (entities.isEmpty()) {
                return "None";
            }
            LivingEntity owner = maid.m_269323_();
            ArrayList entries = Lists.newArrayList();
            entities.stream().sorted(Comparator.comparingDouble(e -> e.m_20280_((Entity)maid))).limit(20L).forEach(entity -> {
                ResourceLocation type = ForgeRegistries.ENTITY_TYPES.getKey((Object)entity.m_6095_());
                if (type == null) {
                    return;
                }
                int id = entity.m_19879_();
                float distToMaid = maid.m_20270_((Entity)entity);
                String entry = owner != null ? "%s (id=%d, dist_self=%.1f, dist_user=%.1f)".formatted(type, id, Float.valueOf(distToMaid), Float.valueOf(owner.m_20270_((Entity)entity))) : "%s (id=%d, dist_self=%.1f)".formatted(type, id, Float.valueOf(distToMaid));
                if (entity instanceof Player) {
                    Player player = (Player)entity;
                    entry = "%s[%s]".formatted(player.m_6302_(), entry);
                }
                entries.add(entry);
            });
            return StringUtils.join((Iterable)entries, (String)", ");
        }
    }
}

