        try {
            SkillBean header;
            String headerText;
            List lines = IOUtils.readLines((InputStream)stream, (Charset)StandardCharsets.UTF_8);
            StringBuilder yamlContent = new StringBuilder();
            boolean isInsideYaml = false;
            int bodyStartIndex = 0;
            for (String line : lines) {
                ++bodyStartIndex;
                if (YAML_FRONT_MATTER.equals(line.trim())) {
                    if (isInsideYaml) break;
                    isInsideYaml = true;
                    continue;
                }
                if (!isInsideYaml) continue;
                yamlContent.append(line).append("\n");
            }
            if ((headerText = yamlContent.toString()).isEmpty()) {
                return null;
            }
            if (bodyStartIndex >= lines.size()) {
                return null;
            }
            String body = String.join((CharSequence)"\n", lines.subList(bodyStartIndex, lines.size())).trim();
            try {
