                return null;
            }
            if (StringUtils.isBlank((CharSequence)header.getName()) || StringUtils.isBlank((CharSequence)header.getDescription())) {
                TouhouLittleMaid.LOGGER.warn("Skip invalid skill yml {} because name or description is missing or blank", (Object)fileName);
                return null;
            }
            if (StringUtils.isBlank((CharSequence)body)) {
                TouhouLittleMaid.LOGGER.warn("Skip invalid skill yml {} because body is missing or blank", (Object)fileName);
                return null;
            }
            return Pair.of((Object)header, (Object)body);
        }
        catch (Exception e) {
            TouhouLittleMaid.LOGGER.warn("Failed to read skill file {}, skipping this skill. Error: {}", (Object)fileName, (Object)e.getMessage());
            return null;
        }
    }
}

