package com.github.tartaricacid.touhoulittlemaid.ai.agent.tool.record;

import com.google.gson.annotations.SerializedName;
import java.util.Map;
import org.apache.commons.lang3.StringUtils;

public class WikiRecord {
    private static final int MAX_TEXT_LENGTH = 4096;

    private record PageEntry(@SerializedName(value="extract") String extract) {
    }

    private record QueryPages(@SerializedName(value="pages") Map<String, PageEntry> pages) {
    }

    private record SearchEntry(@SerializedName(value="title") String title) {
    }

    private record QueryTitle(@SerializedName(value="search") SearchEntry[] search) {
    }

    public record PageExtractResult(@SerializedName(value="query") QueryPages query) {
        public String getFirstExtract() {
            if (this.query == null || this.query.pages == null || this.query.pages.isEmpty()) {
                return "";
            }
            return this.query.pages.values().stream().findFirst().map(PageEntry::extract).filter(StringUtils::isNotBlank).map(extract -> StringUtils.abbreviate((String)extract, (int)4096)).orElse("");
        }
    }

    public record QueryTitleResult(@SerializedName(value="query") QueryTitle query) {
        public String getFirstTitle() {
            if (this.query == null || this.query.search == null || this.query.search.length == 0) {
                return "";
            }
            return this.query.search[0].title;
        }
    }
}

