import com.github.tartaricacid.touhoulittlemaid.ai.manager.entity.grounded.GroundedAnswerPrompts;
import com.github.tartaricacid.touhoulittlemaid.ai.manager.entity.summary.HistorySummaryPrompts;
import com.github.tartaricacid.touhoulittlemaid.ai.manager.response.ResponseChat;
import com.github.tartaricacid.touhoulittlemaid.ai.service.llm.LLMClient;
import com.github.tartaricacid.touhoulittlemaid.ai.service.llm.LLMMessage;
import com.github.tartaricacid.touhoulittlemaid.ai.service.llm.Role;
import com.github.tartaricacid.touhoulittlemaid.ai.service.llm.openai.response.Message;
import com.github.tartaricacid.touhoulittlemaid.entity.passive.EntityMaid;
import com.google.common.collect.Lists;
import java.net.http.HttpRequest;
import java.util.ArrayList;
import java.util.List;
import java.util.StringJoiner;
import java.util.concurrent.CompletableFuture;
import javax.annotation.Nullable;
import org.apache.commons.lang3.StringUtils;

public class GroundedAnswerCallback
extends LLMCallback {
    private static final int MAX_CONTEXT_MESSAGES = 4;
    private final CompletableFuture<String> resultFuture;

    public GroundedAnswerCallback(MaidAIChatManager manager, String knowledge, long waitingChatBubbleId, CompletableFuture<String> resultFuture) {
        super(manager, GroundedAnswerCallback.createGroundedAnswerMessages(manager, knowledge), true);
        this.waitingChatBubbleId = waitingChatBubbleId;
        this.needAddTools = false;
        this.resultFuture = resultFuture;
    }

    @Override
    public boolean shouldCacheTokenUsage() {
        return false;
    }

    @Override
    public void onFunctionCall(Message choice, LLMClient client) {
    }

    @Override
    public void onFailure(@Nullable HttpRequest request, Throwable throwable, int errorCode) {
        String message = "Grounded answer request failed, error code %s: %s".formatted(errorCode, throwable.getMessage());
        this.resultFuture.completeExceptionally(new IllegalStateException(message, throwable));
        TouhouLittleMaid.LOGGER.error(message);
    }

    @Override
    public void onSuccess(ResponseChat responseChat) {
        String text = responseChat.getChatText();
        if (StringUtils.isBlank((CharSequence)text)) {
            this.resultFuture.completeExceptionally(new IllegalStateException("Grounded answer response is blank"));
            return;
        }
        this.resultFuture.complete(text.trim());
    }

    private static List<LLMMessage> createGroundedAnswerMessages(MaidAIChatManager manager, String knowledge) {
        EntityMaid maid = manager.getMaid();
        ArrayList msg = Lists.newArrayList();
        String resolvedQuestion = GroundedAnswerCallback.resolveUserQuestion(manager);
        String userPrompt = GroundedAnswerPrompts.buildUserPrompt(resolvedQuestion, knowledge);
        msg.add(LLMMessage.systemChat(maid, "## Grounded Result Extraction Instructions\nExtract raw facts from the provided knowledge and map them to the core intent of the conversation.\n\n### Mission:\n- **Identify the Subject**: Determine what specific entity the user is currently focused on.\n- **Extract Key-Value Facts**: Extract only the hard facts and pair them with their clear meanings.\n- **Normalize References**: Convert all relative terms (this, it, her) into their specific names based on the conversation history provided below.\n\n### Constraints:\n1. **Output Format**: Use \"Subject > Fact\" or \"Parameter: Value\" style. Be as dry as possible.\n2. **Strictness**: If the knowledge doesn't contain a direct answer, output \"Unknown: [Subject]\".\n3. **No Conversational Noise**: No \"Here is what I found\", no \"Based on the docs\".\n4. **No Formatting**: Plain text only. No Markdown tables or separators.\n"));
        msg.add(LLMMessage.userChat(maid, userPrompt));
        return msg;
    }

    private static String resolveUserQuestion(MaidAIChatManager manager) {
        String latestUser = "";
        ArrayList contextMessages = Lists.newArrayList();
        for (LLMMessage message : manager.getHistory().getDeque()) {
            if (StringUtils.isBlank((CharSequence)latestUser)) {
                if (message.role() != Role.USER || !StringUtils.isNotBlank((CharSequence)message.message())) continue;
                latestUser = message.message();
                continue;
            }
            contextMessages.add(message);
            if (contextMessages.size() < 4) continue;
            break;
        }
        if (StringUtils.isBlank((CharSequence)latestUser)) {
            return "";
        }
        StringJoiner joiner = new StringJoiner("\n");
        for (int i = contextMessages.size() - 1; i >= 0; --i) {
            String entry = HistorySummaryPrompts.buildSummaryEntry((LLMMessage)contextMessages.get(i));
            if (!StringUtils.isNotBlank((CharSequence)entry)) continue;
            joiner.add(entry);
        }
        if (joiner.length() == 0) {
            return latestUser;
        }

