package com.github.tartaricacid.touhoulittlemaid.ai.manager.entity;

import com.github.tartaricacid.touhoulittlemaid.ai.service.llm.LLMMessage;
import com.github.tartaricacid.touhoulittlemaid.ai.service.llm.Role;
import com.github.tartaricacid.touhoulittlemaid.ai.service.llm.openai.response.ToolCall;
import com.google.common.collect.Lists;
import com.google.common.collect.Sets;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

public class HistoryMessagesCheck {
    public static void checkMessages(List<LLMMessage> messages) {
        int systemCount;
        if (messages.size() <= 1) {
            return;
        }
        for (systemCount = 0; systemCount < messages.size() && messages.get(systemCount).role() == Role.SYSTEM; ++systemCount) {
        }
        if (systemCount >= messages.size()) {
            return;
        }
        ArrayList systemMessages = Lists.newArrayList(messages.subList(0, systemCount));
        List conversation = messages.stream().skip(systemCount).dropWhile(msg -> Role.TOOL.equals((Object)msg.role())).collect(Collectors.toCollection(ArrayList::new));
        HistoryMessagesCheck.removeUnpairedToolCalls(conversation);
        messages.clear();
        messages.addAll(systemMessages);
        messages.addAll(conversation);
    }

    private static void removeUnpairedToolCalls(List<LLMMessage> conversation) {
        int i = 0;
        while (i < conversation.size()) {
            int toolStart;
            int toolEnd;
            LLMMessage msg = conversation.get(i);
            if (msg.role() != Role.ASSISTANT || msg.toolCalls() == null || msg.toolCalls().isEmpty()) {
                ++i;
                continue;
            }
            Set expectedIds = msg.toolCalls().stream().map(ToolCall::getId).collect(Collectors.toSet());
            HashSet actualIds = Sets.newHashSet();
            for (toolEnd = toolStart = i + 1; toolEnd < conversation.size() && conversation.get(toolEnd).role() == Role.TOOL; ++toolEnd) {
                String toolCallId = conversation.get(toolEnd).toolCallId();
                if (toolCallId == null) continue;
                actualIds.add(toolCallId);
            }
            if (!actualIds.containsAll(expectedIds)) {
                conversation.set(i, new LLMMessage(msg.role(), msg.message(), msg.gameTime()));
                if (toolEnd <= toolStart) continue;
                conversation.subList(toolStart, toolEnd).clear();
                continue;
            }
            ++i;
        }
    }
}

